function parseUser(raw: unknown): User {
  if (typeof raw !== 'object' || raw === null) throw new Error('invalid');
  if (!('id' in raw) || typeof (raw as User).id !== 'string') {
    throw new Error('id required');
  }
  return raw as User;
}

